    if !self.page_creation.terminal_is_empty(){return self.page_creation.close_work_demand(body)}
    if !self.document.terminal_is_empty(){return self.document.close_work_demand(body)}
    if !self.overrides.terminal_is_empty(){return self.overrides.close_work_demand(body)}
