 pub fn terminal_is_empty(&self)->bool{self.closing&&self.page_creation.terminal_is_empty()&&self.document.terminal_is_empty()&&self.overrides.terminal_is_empty()&&self.spread.terminal_is_empty()&&self.parent.terminal_is_empty()&&self.data.terminal_is_empty()&&self.diff.is_none()&&self.retirement.is_empty()&&self.flight.idle()}
